mapper.select:
select 
  from wms_ship s join mst_cust c on c.cust_id = s.cust_id left join wms_ship_transport tr on tr.ship_id = s.ship_id
 where s.plant_cd = #{plantCd}
 and s.status = #{status}
 and s.plan_date >= #{from}
 and s.plan_date <= #{to}
 order by s.plan_date desc, s.ship_id desc
 limit #{limit}

mapper.sql:
 from wms_ship s join mst_cust c on c.cust_id = s.cust_id left join wms_ship_transport tr on tr.ship_id = s.ship_id
where s.plant_cd = #{plantCd}
and s.status = #{status}
and s.plan_date >= #{from}
and s.plan_date <= #{to}

mapper.update:
update wms_ship_pick set status = #{to}, updated_at = now(), updated_by = #{by}
 where status = #{from}
   and pick_id in #{id}

mapper.select:
with recursive up as (
    select n.node_id, n.parent_id, 1 as lv from mst_equip_hier n where n.node_id = #{nodeId}
    union all
    select p.node_id, p.parent_id, u.lv + 1 from up u join mst_equip_hier p on p.node_id = u.parent_id where u.lv < 20
)
select case when exists (select 1 from up join wms_loc_attr x on x.node_id = up.node_id where x.loc_usage = 'SCRAP') then 'SCRAP'
            else coalesce(a.loc_usage, 'STORAGE') end
  from mst_equip_hier n left join wms_loc_attr a on a.node_id = n.node_id
 where n.node_id = #{nodeId} and n.plant_cd = #{plantCd}

select t.ship_id, s.ship_no, t.pallet_id, t.pallet_no, t.sscc, t.status
  from wms_pallet t
  join wms_ship s on s.ship_id = t.ship_id
 where 
         t.sscc = #{sscc}
         t.pallet_no = #{palletNo}

mapper.update:
update wms_pallet set status = 'CLOSED', sscc = coalesce(sscc, #{sscc}), closed_at = now(), closed_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where pallet_id = #{palletId} and status = 'OPEN'

update wms_pallet set status = #{to}, closed_at = null, closed_by = null, remark = coalesce(#{remark}, remark),
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where pallet_id = #{palletId} and status = #{from}

update wms_ship_pick set pallet_id = #{palletId}, updated_at = now(), updated_by = #{by}
 where status = 'PICKED'
   and pick_id in #{id}
